// cell-management.lambda.ts
import * as path from 'path';
import { PythonFunction, PythonLayerVersion } from '@aws-cdk/aws-lambda-python-alpha';
import { Duration, Stack } from 'aws-cdk-lib';
import { CfnTable } from 'aws-cdk-lib/aws-dynamodb';
import { Effect, ManagedPolicy, PolicyStatement, Role, ServicePrincipal } from 'aws-cdk-lib/aws-iam';
import { Function, LayerVersion, Runtime } from 'aws-cdk-lib/aws-lambda';
import { NagSuppressions } from 'cdk-nag';
import { Construct } from 'constructs';
import { CellManagementTable } from './cell-management.table';
import { IEventManager } from '@cdklabs/sbt-aws';
import { CellManagementService } from './cell-management.service';

export interface CellManagementLambdaProps {
  readonly table: CellManagementTable;
  readonly eventManager: IEventManager;
}

export class CellManagementLambda extends Construct {
  CellManagementFunc: Function;

  constructor(scope: Construct, id: string, props: CellManagementLambdaProps) {
    super(scope, id);

    /**
     * Creates an IAM role for the Tenant Management Lambda function.
     * The role is granted read and write access to the Tenant Details table,
     * and the ability to put events to the Event Manager.
     * The role is also assigned the AWSLambdaBasicExecutionRole,
     * CloudWatchLambdaInsightsExecutionRolePolicy, and AWSXrayWriteOnlyAccess
     * managed policies.
     */
    const CellManagementExecRole = new Role(this, 'CellManagementExecRole', {
      assumedBy: new ServicePrincipal('lambda.amazonaws.com'),
    });

    props.table.deployments.grantReadWriteData(CellManagementExecRole);
    props.table.tenants.grantReadWriteData(CellManagementExecRole);

    CellManagementExecRole.addToPolicy(new PolicyStatement({
      effect: Effect.ALLOW,
      actions: ['dynamodb:Query'],
      resources: [
        `${props.table.deployments.tableArn}/index/*`,
        `${props.table.tenants.tableArn}/index/*`
      ]
    })); props.table.cells.grantReadWriteData(CellManagementExecRole);

    props.eventManager.grantPutEventsTo(CellManagementExecRole);

    CellManagementExecRole.addManagedPolicy(
      ManagedPolicy.fromAwsManagedPolicyName('service-role/AWSLambdaBasicExecutionRole')
    );
    CellManagementExecRole.addManagedPolicy(
      ManagedPolicy.fromAwsManagedPolicyName('CloudWatchLambdaInsightsExecutionRolePolicy')
    );
    CellManagementExecRole.addManagedPolicy(
      ManagedPolicy.fromAwsManagedPolicyName('AWSXrayWriteOnlyAccess')
    );

    NagSuppressions.addResourceSuppressions(
      CellManagementExecRole,
      [
        {
          id: 'AwsSolutions-IAM5',
          reason: 'Index name(s) not known beforehand.',
          appliesTo: [
            `Resource::<${Stack.of(this).getLogicalId(props.table.deployments.node.defaultChild as CfnTable)}.Arn>/index/*`,
            `Resource::<${Stack.of(this).getLogicalId(props.table.tenants.node.defaultChild as CfnTable)}.Arn>/index/*`,
            `Resource::<${Stack.of(this).getLogicalId(props.table.cells.node.defaultChild as CfnTable)}.Arn>/index/*`,
          ],
        },
        {
          id: 'AwsSolutions-IAM4',
          reason:
            'Suppress usage of AWSLambdaBasicExecutionRole, CloudWatchLambdaInsightsExecutionRolePolicy, and AWSXrayWriteOnlyAccess.',
          appliesTo: [
            'Policy::arn:<AWS::Partition>:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole',
            'Policy::arn:<AWS::Partition>:iam::aws:policy/CloudWatchLambdaInsightsExecutionRolePolicy',
            'Policy::arn:<AWS::Partition>:iam::aws:policy/AWSXrayWriteOnlyAccess',
          ],
        },
      ],
      true // applyToChildren = true, so that it applies to policies created for the role.
    );

    // https://docs.powertools.aws.dev/lambda/python/2.31.0/#lambda-layer
    const lambdaPowerToolsLayerARN = `arn:aws:lambda:${Stack.of(this).region
      }:017000801446:layer:AWSLambdaPowertoolsPythonV2:59`;

    const awsRequestsAuthLayer = new PythonLayerVersion(this, 'AwsRequestsAuthLayer', {
      entry: path.join(__dirname, '../lambda/layers/helper'),
      compatibleRuntimes: [Runtime.PYTHON_3_12],
    });

    /**
     * Creates the Tenant Management Lambda function.
     * The function is configured with the necessary environment variables,
     * the Tenant Management execution role, and the AWS Lambda Powertools layer.
     */
    const CellManagementFunc = new PythonFunction(this, 'CellManagementServices', {
      entry: path.join(__dirname, '../lambda/cell-management'),
      runtime: Runtime.PYTHON_3_12,
      index: 'index.py',
      handler: 'lambda_handler',
      timeout: Duration.seconds(60),
      role: CellManagementExecRole,
      layers: [
        LayerVersion.fromLayerVersionArn(this, 'LambdaPowerTools', lambdaPowerToolsLayerARN),
        awsRequestsAuthLayer
      ],
      environment: {
        TENANTS_TABLE_NAME: props.table.tenants.tableName,
        CELLs_TABLE_NAME: props.table.cells.tableName,
        DEPLOYMENTS_TABLE_NAME: props.table.deployments.tableName,
        EVENTBUS_NAME: props.eventManager.busName,
        EVENT_SOURCE: props.eventManager.controlPlaneEventSource,
        CELL_MANAGEMENT_DETAIL_TYPE: CellManagementService.ONBOARDING_CELL_REQUEST,
      },
    });

    this.CellManagementFunc = CellManagementFunc;
  }
}
